const $=id=>document.getElementById(id);let recorder,stream,chunks=[],blob,previewURL,timer,group,uploading=false;
function stopTracks(){stream?.getTracks().forEach(track=>track.stop());stream=null;clearTimeout(timer)}
function discard(){if(recorder?.state==='recording'){recorder.onstop=null;recorder.stop()}stopTracks();recorder=null;blob=null;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=null;$('voice-preview').removeAttribute('src');$('voice-preview').hidden=true;$('voice-attach').disabled=true;$('voice-record').textContent='Record';$('voice-status').textContent='Record up to 60 seconds, or choose an audio file (8 MB maximum).'}
function preview(value){if(!value.size||value.size>8000000){$('voice-status').textContent='Clip is empty or exceeds 8 MB.';return}blob=value;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=URL.createObjectURL(blob);$('voice-preview').src=previewURL;$('voice-preview').hidden=false;$('voice-attach').disabled=false;$('voice-status').textContent='Listen to your clip, then attach it. It will not send until you press Send.'}
$('voice-open').onclick=()=>{group=window.DockGroupMeAudioTarget.current();if(!group)return;discard();$('voice-dialog').showModal()};
$('voice-record').onclick=async()=>{if(uploading)return;if(recorder?.state==='recording'){recorder.stop();return}try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Recording is unavailable. Choose an audio file instead.');stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!$('voice-dialog').open){stopTracks();return}const type=['audio/mp4','audio/webm;codecs=opus','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported(t));if(!type)throw Error('This browser cannot record a supported audio format. Choose a file instead.');chunks=[];recorder=new MediaRecorder(stream,{mimeType:type});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{stopTracks();$('voice-record').textContent='Record again';preview(new Blob(chunks,{type:recorder.mimeType}))};recorder.start();$('voice-record').textContent='Stop recording';$('voice-status').textContent='Recording… microphone active. Stops automatically after 60 seconds.';$('voice-attach').disabled=true;timer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},60000)}catch(error){stopTracks();$('voice-status').textContent=error.message}};
$('voice-file').onchange=()=>{if(recorder?.state==='recording'||uploading)return;const file=$('voice-file').files?.[0];$('voice-file').value='';if(file)preview(file)};
$('voice-attach').onclick=async()=>{if(!blob||uploading)return;uploading=true;for(const id of ['voice-record','voice-file','voice-attach'])$(id).disabled=true;$('voice-status').textContent='Uploading voice clip…';try{const response=await fetch('/api/groupme/audio?group='+encodeURIComponent(group),{method:'POST',credentials:'same-origin',headers:{'Content-Type':blob.type},body:blob,signal:AbortSignal.timeout(90000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Upload failed.');window.DockGroupMeAudioTarget.attach(group,data.response.url);$('voice-dialog').close()}catch(error){$('voice-status').textContent=error.message}finally{uploading=false;for(const id of ['voice-record','voice-file'])$(id).disabled=false;$('voice-attach').disabled=!blob}};
$('voice-close').onclick=()=>{if(!uploading)$('voice-dialog').close()};$('voice-dialog').addEventListener('close',discard);$('voice-dialog').addEventListener('cancel',event=>{if(uploading)event.preventDefault()});window.addEventListener('pagehide',discard);
